import {haloIllustration} from '../halo-display.js';
const urlSettings=new URLSearchParams(location.search);const readSetting=(key,fallback,max)=>{const raw=urlSettings.get(key),value=Number(raw);return raw!==null&&Number.isFinite(value)&&value>=0&&value<=max?value:fallback;};
const $=id=>document.getElementById(id);const worker=new Worker('../illustration-worker.js',{type:'module'});const photo=new Image();photo.src='../pj-night.png';let ready=false,current={},request=0,cache=new Map(),lastKey='',readers=false,rotated=readSetting('rotation',0,30),haloStrength=readSetting('halo',30,100)/100;const pendingKeys=new Map(),readersByScene={reading:urlSettings.get('readingGlasses')==='on',arm:urlSettings.get('armGlasses')==='on'};photo.onload=()=>{ready=true;updateIllustration(current);};photo.onerror=()=>{$('visual-status').textContent='Photo unavailable. Please try the reading scene. ';};
const dayPhoto=new Image();let dayReady=false;dayPhoto.onload=()=>{dayReady=true;updateIllustration(current);};dayPhoto.onerror=()=>{$('visual-status').textContent='Daytime photo unavailable. Please try night or reading. ';};
const armPhoto=new Image();let armReady=false;armPhoto.onload=()=>{armReady=true;updateIllustration(current);};armPhoto.onerror=()=>{$('visual-status').textContent='Guava image unavailable. Please try another scene. ';};
const input=document.createElement('canvas');input.width=640;input.height=360;const ctx=input.getContext('2d',{willReadFrequently:true});
function source(scene){ctx.textAlign='left';if(scene==='night'){ctx.drawImage(photo,0,0,640,360);}else if(scene==='everyday'){ctx.drawImage(dayPhoto,0,0,640,360);}else if(scene==='arm'){ctx.drawImage(armPhoto,0,0,640,360);}else{ctx.fillStyle='#eae4d8';ctx.fillRect(0,0,640,360);ctx.fillStyle='#fffaf0';ctx.fillRect(45,28,550,304);ctx.fillStyle='#b5a789';ctx.fillRect(45,28,5,304);ctx.fillStyle='#28312f';ctx.font='bold 16px sans-serif';ctx.fillText('A quiet morning',78,65);ctx.font='25px sans-serif';ctx.textAlign='center';['Morning light fills the garden. ','Small birds rest among the leaves. ','We will walk in the park today. '].forEach((s,i)=>ctx.fillText(s,320,118+i*43));ctx.fillStyle='#68716a';ctx.font='20px Georgia';ctx.fillText('Clear details make reading easier. ',320,267);ctx.font='13px sans-serif';ctx.fillText('Illustrative text, not an eye chart',320,307);}return ctx.getImageData(0,0,640,360).data;}
function paint(d){const a=new ImageData(current.topic!=='astigmatism'&&['reading','arm'].includes(current.situation)&&!readers?d.blur:d.clear,640,360),b=new ImageData(current.topic!=='astigmatism'?haloIllustration(d.clear,d.multi,haloStrength):d.multi,640,360);$('visual-a').getContext('2d').putImageData(a,0,0);$('visual-b').getContext('2d').putImageData(b,0,0);$('visual-status').textContent='';}
function diagram(which){const g=$(which==='a'?'visual-a':'visual-b').getContext('2d');g.fillStyle='#0c1d26';g.fillRect(0,0,640,360);g.fillStyle='#c6d6dd';g.font='22px system-ui';g.textAlign='center';g.fillText('Useful viewing range · Concept only',320,68);g.strokeStyle='#55707c';g.lineWidth=3;g.beginPath();g.moveTo(80,220);g.lineTo(560,220);g.stroke();const labels=['Distance','Arm’s length','Near'];labels.forEach((v,i)=>{g.fillStyle='#dae4e8';g.font='21px system-ui';g.fillText(v,80+i*240,266);g.beginPath();g.arc(80+i*240,220,5,0,Math.PI*2);g.fill();});g.strokeStyle=which==='a'?'#9be4d2':'#f0c39d';g.lineWidth=22;g.lineCap='round';g.beginPath();g.moveTo(80,167);g.lineTo(which==='a'?95:current.lens==='enhanced'?235:320,167);g.stroke();g.font='18px system-ui';g.fillStyle='#c6d6dd';g.fillText(which==='a'?'One main distance focus':current.lens==='enhanced'?'Some added intermediate range':'Range extends towards intermediate',320,315);g.font='15px system-ui';g.fillText('Not a measured range or acuity scale',320,99);}
export function updateIllustration(state){if(!state?.situation)return;if(state.situation==='everyday'&&!dayPhoto.getAttribute('src'))dayPhoto.src='../pj-day.png';if(state.situation==='arm'&&!armPhoto.getAttribute('src'))armPhoto.src='../pj-guava.png';if(current.situation!==state.situation)readers=readersByScene[state.situation]||false;current=state;const astig=state.topic==='astigmatism',diagramMode=!astig&&state.lens!=='multi';$('halo-control').hidden=diagramMode||astig;$('rotation-control').hidden=!astig;$('alternatives').hidden=astig;$('visual').dataset.view=state.view;$('visual').dataset.scene=state.situation;$('visual').dataset.diagram=String(diagramMode);$('readers-control').hidden=!['reading','arm'].includes(state.situation)||diagramMode||astig;syncGlasses(['reading','arm'].includes(state.situation)&&!diagramMode&&!astig);$('visual-a-label').textContent=diagramMode?'A · Monofocal':['reading','arm'].includes(state.situation)?(readers?'A · Monofocal + matching glasses':'A · Monofocal without glasses'):'A · Monofocal illustration';$('visual-b-label').textContent=diagramMode?'B · '+(state.lens==='enhanced'?'Enhanced monofocal':state.lens==='edof'?'EDOF':'Multifocal'):'B · Multifocal visual illustration';$('visual-note').textContent=diagramMode?'Conceptual focus range, not the performance of a specific model. ':'Illustration, not a vision prediction';$('visual-detail').textContent=diagramMode?'Lengths illustrate a concept; they are not clinical measurements. ':state.situation==='arm'?'Guava target assumed at 80 cm. Both start without glasses; A can add the power for this distance. ':state.situation==='reading'?'The same page at 40 cm. Both start without glasses; A can add reading glasses. ':state.situation==='everyday'?'PJ-style distance scene. The slider changes the halo/haze illustration, not a postoperative prediction. ':'PJ-style night scene with adjustable illustrated halos. Not clinically calibrated; actual impact varies by person and model. ';if(astig){$('visual-a-label').textContent='A · Astigmatism glasses';$('visual-b-label').textContent=rotated?'B · Toric rotated '+rotated+'°':'B · Toric aligned';$('visual-note').textContent='Same single-focus optics · Example: 1.00 D regular astigmatism';$('visual-detail').textContent=(rotated?'This rotation leaves B with about '+(2*Math.sin(rotated*Math.PI/180)).toFixed(2)+'  D of residual astigmatism. ':'Both corrections match in the ideal model. ')+(state.situation==='arm'?'Both sides include ideal additional power for 80 cm. ':state.situation==='reading'?'Both sides include ideal additional power for 40 cm reading. ':'')+'These are not personal measurements or a vision prediction. ';}if(diagramMode){lastKey='';diagram('a');diagram('b');$('visual-status').textContent='';return;}if((state.situation==='night'&&!ready)||(state.situation==='everyday'&&!dayReady)||(state.situation==='arm'&&!armReady)){$('visual-status').textContent='Loading image…';return;}const key=getKey();if(cache.has(key)){paint(cache.get(key));return;}if(lastKey===key)return;lastKey=key;$('visual-status').textContent='Calculating image…';// Blank old images while a new situation is calculating.
for(const id of ['visual-a','visual-b']){const g=$(id).getContext('2d');g.fillStyle='#09161e';g.fillRect(0,0,640,360);}const id=++request;pendingKeys.set(id,key);worker.postMessage({id,scene:state.situation,topic:state.topic,rotated,input:source(state.situation)});}
worker.onmessage=({data:d})=>{const key=pendingKeys.get(d.id);pendingKeys.delete(d.id);if(d.id!==request)return;if(d.error){$('visual-status').textContent='Image unavailable. Open Details to read the comparison. ';lastKey='';return;}cache.set(key,d);if(cache.size>12)cache.delete(cache.keys().next().value);if((current.topic==='astigmatism'||current.lens==='multi')&&getKey()===key)paint(d);};worker.onerror=()=>{$('visual-status').textContent='Image unavailable. Open Details to read the comparison. ';};
$('visual-divider').oninput=()=>{$('visual').style.setProperty('--divider',$('visual-divider').value+'%');};
function syncGlasses(visible){
  $('glasses-dock').hidden=!visible;
  $('glasses-dock').dataset.on=String(readers);
  $('glasses-handle').setAttribute('aria-checked',String(readers));
  $('glasses-handle').style.removeProperty('transform');
  $('glasses-state').textContent=readers?'Glasses on':'Glasses off';
}
function wearGlasses(value){readers=value;readersByScene[current.situation]=value;updateIllustration(current);}
let glassesDrag=null;
$('glasses-handle').onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();glassesDrag={y:e.clientY,on:readers};e.currentTarget.setPointerCapture(e.pointerId);};
$('glasses-handle').onpointermove=e=>{if(!glassesDrag)return;const travel=44;const position=Math.max(0,Math.min(travel,(glassesDrag.on?travel:0)+e.clientY-glassesDrag.y));e.currentTarget.style.transform='translateY('+position+'px)';};
$('glasses-handle').onpointerup=e=>{if(!glassesDrag)return;const dy=e.clientY-glassesDrag.y;glassesDrag=null;wearGlasses(Math.abs(dy)>12?dy>0:!readers);};
