function getKey(){return (current.topic||'lens')+':'+current.situation+':'+(current.topic==='astigmatism'?String(rotated):'aligned');}
function describeRotation(value){const residual=2*Math.sin(value*Math.PI/180);$('rotation-value').textContent=(value?value+'°':'Aligned')+' · Residual '+residual.toFixed(2)+' D';$('rotation-example').setAttribute('aria-valuetext',value+'degrees rotation; residual astigmatism in B: '+residual.toFixed(2)+' D');}
