$('rotation-example').oninput=()=>{const value=Number($('rotation-example').value);describeRotation(value);clearTimeout(rotationTimer);$('visual-status').textContent='Updating astigmatism illustration…';rotationTimer=setTimeout(()=>{rotated=value;updateIllustration(current);},180);};


